import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"スタートアップパネル","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/startup-panel.md","filePath":"ja-JP/user-guide/settings/startup-panel.md","lastUpdated":1785587987000}'),o={name:"ja-JP/user-guide/settings/startup-panel.md"};function n(l,a,i,d,h,p){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="スタートアップパネル" tabindex="-1">スタートアップパネル <a class="header-anchor" href="#スタートアップパネル" aria-label="Permalink to &quot;スタートアップパネル&quot;">​</a></h1><p>検索ボックスが空のときにクイックウィンドウの結果リストの上に表示されるタブストリップで、クエリを入力しなくても最近使ったファイル、お気に入り、履歴にすばやくアクセスできます。</p><ul><li><strong>スタートアップパネルを有効にする</strong> — マスタースイッチ。オフにすると、以下のタブごとの設定にかかわらずパネルはまったく起動しません。</li></ul><p>4つのサブタブがあります:<strong>最近使ったファイル</strong>、<strong>最後のフォルダー</strong>、<strong>プラグインタブ</strong>、<strong>タブの順序</strong>。</p><h2 id="最近使ったファイル" tabindex="-1">最近使ったファイル <a class="header-anchor" href="#最近使ったファイル" aria-label="Permalink to &quot;最近使ったファイル&quot;">​</a></h2><ul><li><strong>パネルを有効にする</strong> — チェックボックス。検索ボックスが空のときにタブを表示します。</li><li><strong>ディレクトリ</strong> — 監視対象のフォルダーを1行ずつ指定します(<a href="./index-drives.html#除外ルール">除外ルール</a>と同じ、行の追加/編集/削除および一括テキスト編集に対応)。ローカルドライブ、マッピングされたネットワークドライブ、WSL パス(<code>\\\\wsl$\\...</code> または <code>\\\\wsl.localhost\\...</code>)を含められます — <a href="./index-drives.html">インデックス</a>ですでに設定・インデックス済みのものと照合されます。</li><li><strong>表示するファイルの最大数</strong> — 範囲は1~100、デフォルトは10。</li><li><strong>時間範囲(分)</strong> — 上記の件数上限に加えて、現在からこの分数以内に変更されたファイルのみが対象になります。範囲は1~43200(30日)、デフォルトは60。</li></ul><p>ファイルだけで、フォルダーは並びません:フォルダー自身の更新日時は、中に何かが追加されたり削除されたりするたびに変わります。そのため作業中のディレクトリではフォルダーが常に「最も新しいもの」に入り込み、この一覧が本来見せたいものを押し出してしまっていました。</p><p>各エントリの2行目には、インデックスにすでに保存されているそのファイルの最終更新タイムスタンプから生成された相対時間(「X秒/分/時間/日前」)が接頭辞として付きます。そのため追加のディスクアクセスは発生しません。時間と日は、値がゼロの場合はより小さい単位を省略します(例:「2時間0分前」ではなく「2時間前」)。</p><h2 id="最後のフォルダー" tabindex="-1">最後のフォルダー <a class="header-anchor" href="#最後のフォルダー" aria-label="Permalink to &quot;最後のフォルダー&quot;">​</a></h2><ul><li><strong>パネルを有効にする</strong> — チェックボックス。デフォルトでオン。</li></ul><p>SwiftList 独自のダイアログ介入機能が有効な間に、ネイティブのファイルを開く/保存ダイアログが最後に移動したフォルダーの内容を表示します — パスを覚えていなくても、直前にファイル選択ダイアログで参照していた場所にすばやく戻れます。実際のインデックスと同じ隠しファイル/システムファイルのフィルタリングと<a href="./index-drives.html#除外ルール">除外ルール</a>がここにも適用されるため、<code>$RECYCLE.BIN</code> のようなものは表示されません。今回のセッションでまだそれが発生していない場合、フォルダーがすでに存在しない場合、またはそれがデスクトップである場合(単なるデフォルトの着地点であることが多く、実際のナビゲーション先ではないため)、このタブはまったく表示されません。</p><h2 id="プラグインタブ" tabindex="-1">プラグインタブ <a class="header-anchor" href="#プラグインタブ" aria-label="Permalink to &quot;プラグインタブ&quot;">​</a></h2><p>プラグインが提供するタブ(履歴、お気に入りなど)には、ライブパネル内に <strong>×</strong> ボタンがあり、それぞれを一時的に非表示にできます。これはパネル限定の「非表示にする」選択であり、<a href="./plugins.html">プラグイン</a>でプラグインコンポーネント自体を無効化してまったく使用できなくするのとは別のものです。この方法で閉じたタブはここに、提供元のプラグインごとにグループ化されて未チェックの状態で一覧表示されます。チェックすると元に戻ります。</p><p>このリストに表示されるのは、プラグインコンポーネントが現在有効になっているタブのみです。<a href="./plugins.html">プラグイン</a>で完全に無効化されているものは、そもそもタブの候補にすらなりません。</p><h2 id="タブの順序" tabindex="-1">タブの順序 <a class="header-anchor" href="#タブの順序" aria-label="Permalink to &quot;タブの順序&quot;">​</a></h2><p>設定内の他の場所でも使われている上下矢印(またはドラッグでの並べ替え)リストです(「<a href="./favorites.html">お気に入り</a>」を参照)が、これはパネルのタブストリップ全体、つまり組み込みタブ(最近使ったファイル、最後のフォルダー)と現在表示されているすべてのプラグインタブをまとめた1つのフラットなリストを対象とします。プラグインごとにグループ化する上のプラグインタブとは異なります。タブを上下に移動すると、他のタブとの相対的な位置が変わります。このリストの左右の並びが、ライブパネルでの左右の並びになります。</p><p>現在実際に表示されるタブのみが一覧に表示されます。上で無効化した最近使ったファイル/最後のフォルダーのタブや、<strong>×</strong> ボタンで閉じたプラグインタブは、再度有効化または再表示されるまで並べ替える対象がありません。</p>',17)])])}const c=t(o,[["render",n]]);export{u as __pageData,c as default};
